// Same key/value parsing as TL3 "Read Config" (accepts Khoá/Khóa/Key and Giá trị/Value).
const cfg = {};
for (const item of $input.all()) {
  const key = item.json['Khoá'] ?? item.json['Khóa'] ?? item.json['Key'];
  if (key === undefined || key === null || String(key).trim() === '') continue;
  const value = item.json['Giá trị'] ?? item.json['Value'] ?? '';
  cfg[String(key).trim()] = typeof value === 'string' ? value.trim() : value;
}
const required = ['SITE_URL', 'GITHUB_REPO', 'GITHUB_BRANCH', 'APPROVER_EMAILS', 'ADMIN_EMAIL'];
const missing = required.filter((k) => !cfg[k] || String(cfg[k]).trim() === '');
if (missing.length) throw new Error('Config thiếu khoá: ' + missing.join(', '));
return [{ json: cfg }];

// P (Thực đơn): pick at most ONE fully approved week and render its JSON file.
// Deterministic only: no model. Hash must match scripts/newton/approval-stamp.gs exactly.
const crypto = require('crypto');
const cfg = $('Đọc Config').first().json;
const EXCLUDE = ['Trạng thái','Duyệt','Người duyệt','Thời điểm duyệt','Mã băm duyệt','Đã đăng','URL','Commit SHA','Đã xác minh lúc','Ghi chú','QA điểm','QA ghi chú','Mô hình','Phiên bản prompt'];
const STOP = ['Lỗi ✘', 'Bị chặn: PII'];
const s = (v) => String(v ?? '').trim();
const isTrue = (v) => v === true || s(v).toLowerCase() === 'true';
const allow = s(cfg.APPROVER_EMAILS).split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const AT = /^\d{2}\/\d{2}\/\d{4} \d{2}:\d{2}$/;

function parseVn(t) {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s(t));
  if (!m) return null;
  const d = new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  return d.getUTCDate() === +m[1] && d.getUTCMonth() === +m[2] - 1 ? d : null;
}
const fmt = (d) => `${String(d.getUTCDate()).padStart(2, '0')}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${d.getUTCFullYear()}`;
function isoWeek(d) {
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - day);
  const y = t.getUTCFullYear();
  const w = Math.ceil(((t - Date.UTC(y, 0, 1)) / 86400000 + 1) / 7);
  return { y, w };
}
function rowHash(r) {
  const pairs = [];
  for (const [k, v] of Object.entries(r)) {
    const name = s(k), val = s(v);
    if (!name || name === 'row_number' || EXCLUDE.includes(name) || val === '') continue;
    pairs.push(name + '=' + val);
  }
  pairs.sort();
  return crypto.createHash('sha256').update(pairs.join('␟'), 'utf8').digest('hex');
}
// SW-04 deterministic patterns (NEWTON-BUILD-INSTRUCTIONS 8.6.1). Only hit TYPES are reported.
const PII = [
  ['phone', /(?:\+?84|0)(?:[235789])\d{8}\b/],
  ['phone', /\b0\d{2,3}[ .-]?\d{3,4}[ .-]?\d{3,4}\b/],
  ['cccd', /\b\d{9}\b|\b\d{12}\b/],
  ['child-name', /(?:^|[^\p{L}])(?:bé|con|cháu|học sinh)\s+\p{Lu}\p{Ll}+(?:\s+\p{Lu}\p{Ll}+){0,2}/u],
];
const MEALS = ['Bữa sáng', 'Bữa trưa', 'Bữa chiều', 'Bữa phụ'];
const toAt = (t) => { const m = /^(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2})/.exec(s(t)); return m ? `${m[1]}/${m[2]}/${m[3]} ${m[4]}:${m[5]}` : ''; };
const atKey = (t) => { const m = /^(\d{2})\/(\d{2})\/(\d{4}) (\d{2}):(\d{2})/.exec(s(t)); return m ? `${m[3]}${m[2]}${m[1]}${m[4]}${m[5]}` : ''; };

const rows = $input.all().map((i) => i.json).filter((r) => r.row_number !== undefined);
const weeks = new Map();
for (const r of rows) {
  const k = s(r['Tuần bắt đầu']);
  if (!k) continue;
  if (!weeks.has(k)) weeks.set(k, []);
  weeks.get(k).push(r);
}

const out = [];
const status = (r, st, note, audit = {}) => {
  if (s(r['Trạng thái']) === st && s(r['Ghi chú']) === note) return; // nothing changes: no write
  out.push({ json: { kind: 'status', row_number: r.row_number,
    values: { 'Trạng thái': st, 'Ghi chú': note },
    audit: { action: 'kiểm tra', result: st, commit_sha: '', approver: s(r['Người duyệt']), note, ...audit } } });
};

const publishable = [];
for (const [wk, list] of weeks) {
  const candidate = list.some((r) => isTrue(r['Duyệt']) && !isTrue(r['Đã đăng']) && !STOP.includes(s(r['Trạng thái'])));
  if (!candidate) continue;
  const start = parseVn(wk);
  if (!start || start.getUTCDay() !== 1) {
    list.forEach((r) => status(r, 'Thiếu thông tin', 'Tuần bắt đầu phải là ngày thứ 2, dạng DD/MM/YYYY'));
    continue;
  }
  const seen = new Set();
  let ok = true;
  const days = [];
  for (const r of list) {
    const d = parseVn(r['Ngày']);
    const off = d ? Math.round((d - start) / 86400000) : -1;
    if (!d || off < 0 || off > 5 || seen.has(off)) { status(r, 'Thiếu thông tin', 'Ngày không thuộc tuần (thứ 2–7) hoặc bị trùng'); ok = false; continue; }
    seen.add(off);
    const missing = MEALS.slice(0, 3).filter((m) => !s(r[m]));
    if (missing.length) { status(r, 'Thiếu thông tin', 'Thiếu: ' + missing.join(', ')); ok = false; continue; }
    const hits = [...new Set(PII.filter(([, re]) => MEALS.some((m) => re.test(s(r[m])))).map(([t]) => t))];
    if (hits.length) { status(r, 'Bị chặn: PII', 'Nghi có dữ liệu cá nhân: ' + hits.join(', ') + '. Sửa nội dung rồi duyệt lại'); ok = false; continue; }
    if (!isTrue(r['Duyệt'])) { status(r, 'Chờ duyệt', 'Chưa duyệt'); ok = false; continue; }
    const by = s(r['Người duyệt']).toLowerCase();
    if (!by || !allow.includes(by) || !s(r['Mã băm duyệt'])) { status(r, 'Chờ duyệt', 'Người duyệt không thuộc APPROVER_EMAILS hoặc thiếu mã băm'); ok = false; continue; }
    if (rowHash(r) !== s(r['Mã băm duyệt'])) { status(r, 'Đã sửa sau duyệt', 'Nội dung đã sửa sau khi duyệt, cần duyệt lại'); ok = false; continue; }
    days.push({ off, r });
  }
  if (!ok) continue;
  const weekdays = [0, 1, 2, 3, 4].every((o) => seen.has(o));
  if (!weekdays) {
    list.forEach((r) => status(r, 'Chờ duyệt', 'Tuần chưa đủ 5 ngày (thứ 2–6) đã duyệt'));
    continue;
  }
  publishable.push({ wk, start, days, list });
}

publishable.sort((a, b) => a.start - b.start);
const pick = publishable[0]; // one week (one commit) per run
if (pick) {
  const ordered = pick.days.sort((a, b) => a.off - b.off).slice(0, 6);
  const days = ordered.map(({ r }) => {
    const d = { date: s(r['Ngày']), breakfast: s(r['Bữa sáng']), lunch: s(r['Bữa trưa']), afternoon: s(r['Bữa chiều']) };
    if (s(r['Bữa phụ'])) d.snack = s(r['Bữa phụ']);
    return d;
  });
  const latest = [...ordered].sort((a, b) => atKey(b.r['Thời điểm duyệt']).localeCompare(atKey(a.r['Thời điểm duyệt'])))[0].r;
  const approver = s(latest['Người duyệt']).toLowerCase();
  if (!EMAIL.test(approver)) throw new Error('Email người duyệt không hợp lệ ở dòng ' + latest.row_number);
  const week_start = fmt(pick.start);
  const file = { week_start, days, approved: true, approved_by: approver };
  const at = toAt(latest['Thời điểm duyệt']);
  if (AT.test(at)) file.approved_at = at;
  const rowNums = ordered.map(({ r }) => Number(r.row_number)).sort((a, b) => a - b);
  file.sheet_row = rowNums[0];
  file.content_hash = crypto.createHash('sha256').update(JSON.stringify({ week_start, days }), 'utf8').digest('hex');
  file.source = 'n8n';
  const { y, w } = isoWeek(pick.start);
  const slug = `${y}-W${String(w).padStart(2, '0')}`;
  const text = JSON.stringify(file, null, 2) + '\n';
  out.push({ json: {
    kind: 'publish', slug, path: `src/data/menus/${slug}.json`,
    contentBase64: Buffer.from(text, 'utf8').toString('base64'), contentHash: file.content_hash,
    rows: rowNums, approver,
    repo: s(cfg.GITHUB_REPO), branch: s(cfg.GITHUB_BRANCH),
    pageUrl: s(cfg.SITE_URL).replace(/\/+$/, '') + '/giao-duc-tuyen-sinh/thuc-don/',
    commitMessage: `content(thuc-don): ${slug} [sheet:Thực đơn#${rowNums[0]}-${rowNums[rowNums.length - 1]}] approved-by:${approver}`,
  } });
}
return out;

// Compare the rendered file with what is already on GitHub (idempotency).
const pub = $('Chọn tuần cần đăng').all().map((i) => i.json).find((j) => j.kind === 'publish');
const res = $input.first().json;
const code = Number(res.statusCode);
const rowsStatus = (st, values, note, extra = {}) => pub.rows.map((rn) => ({ json: {
  kind: 'status', row_number: rn, values: { 'Trạng thái': st, 'Ghi chú': note, ...values },
  audit: { action: 'đăng thực đơn ' + pub.slug, result: st, commit_sha: extra.sha || '', approver: pub.approver, note } } }));

if (code === 404) return [{ json: { ...pub, kind: 'commit', sha: null } }];
if (code === 200) {
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  let existing = null;
  try { existing = JSON.parse(Buffer.from(String(body.content || ''), 'base64').toString('utf8')); } catch (e) { existing = null; }
  if (existing && existing.content_hash === pub.contentHash && existing.approved === true) {
    return rowsStatus('Đã đăng ✔', { 'Đã đăng': true, 'URL': pub.pageUrl }, 'Đã có trên repo, không đổi');
  }
  return [{ json: { ...pub, kind: 'commit', sha: body.sha } }];
}
const msg = String((res.body && res.body.message) || '').replace(/(gh[p]_|github[_]pat_)\S+/g, '***').slice(0, 150);
return rowsStatus('Lỗi ✘', {}, `GitHub lỗi ${code || '?'} khi đọc file: ${msg}`);

// PUT succeeded: mark every row of the week as published (deploy not verified yet: V is not built).
const pub = $('So sánh với repo').all().map((i) => i.json).find((j) => j.kind === 'commit');
const res = $input.first().json;
const sha = String((res.commit && res.commit.sha) || '');
const note = 'Đã commit, chưa xác minh deploy (V chưa có)';
return pub.rows.map((rn) => ({ json: {
  kind: 'status', row_number: rn,
  values: { 'Trạng thái': 'Đã đăng ✔', 'Đã đăng': true, 'URL': pub.pageUrl, 'Commit SHA': sha, 'Ghi chú': note },
  audit: { action: 'đăng thực đơn ' + pub.slug, result: 'Đã đăng ✔', commit_sha: sha, approver: pub.approver, note } } }));

// PUT failed after retries: rows wait for a human (status Lỗi ✘ is not retried automatically).
const pub = $('So sánh với repo').all().map((i) => i.json).find((j) => j.kind === 'commit');
const e = $input.first().json || {};
const raw = (e.error && (e.error.message || e.error.description)) || e.message || JSON.stringify(e.error || e).slice(0, 200);
const msg = String(raw).replace(/(gh[p]_|github[_]pat_)\S+/g, '***').slice(0, 150);
const note = 'GitHub lỗi khi commit: ' + msg + '. Xoá trạng thái để thử lại';
return pub.rows.map((rn) => ({ json: {
  kind: 'status', row_number: rn, values: { 'Trạng thái': 'Lỗi ✘', 'Ghi chú': note },
  audit: { action: 'đăng thực đơn ' + pub.slug, result: 'Lỗi ✘', commit_sha: '', approver: pub.approver, note } } }));

const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).formatToParts(new Date()).map((x) => [x.type, x.value]));
const now = `${p.day}/${p.month}/${p.year} ${p.hour}:${p.minute}:${p.second}`;
return $input.all().map((i) => ({ json: {
  'Thời điểm': now, 'Workflow': 'P', 'Tab': 'Thực đơn', 'Dòng': i.json.row_number,
  'Hành động': i.json.audit?.action || '', 'Kết quả': i.json.audit?.result || '',
  'Commit SHA': i.json.audit?.commit_sha || '', 'Người duyệt': i.json.audit?.approver || '',
  'Mô hình': '', 'Ghi chú': i.json.audit?.note || '' } }));

// One email per run for rows that need a person. Row numbers + statuses only, never cell text.
const ALERT = ['Lỗi ✘', 'Bị chặn: PII', 'Đã sửa sau duyệt'];
const hits = $input.all().map((i) => i.json).filter((j) => ALERT.includes(j.values?.['Trạng thái']));
if (!hits.length) return [];
const cfg = $('Đọc Config').first().json;
const lines = hits.map((h) => `<li>Thực đơn dòng ${h.row_number}: <b>${h.values['Trạng thái']}</b></li>`).join('');
return [{ json: {
  to: cfg.ADMIN_EMAIL || '', from: cfg.SMTP_FROM || cfg.ADMIN_EMAIL || '',
  subject: `[Newton] P - ${hits.length} dòng thực đơn cần xử lý`,
  html: `<p>Workflow P (đăng thực đơn) cần người xử lý:</p><ul>${lines}</ul><p>Mở Google Sheet "Newton – Website", tab Thực đơn, xem cột Ghi chú.</p>` } }];
